import 'dart:convert';import 'package:flutter_secure_storage/flutter_secure_storage.dart';import 'package:http/http.dart' as http;
class ApiClient{ApiClient._();static final instance=ApiClient._();static const baseUrl=String.fromEnvironment('API_URL',defaultValue:'http://10.0.2.2:5000');final storage=const FlutterSecureStorage();String? token;Future<String?> requestOtp(String phone)async{final r=await http.post(Uri.parse('$baseUrl/api/auth/otp/request'),headers:{'Content-Type':'application/json'},body:jsonEncode({'phone':phone}));if(r.statusCode<200||r.statusCode>=300)throw Exception('Не удалось отправить OTP');return jsonDecode(r.body)['devCode']?.toString();}Future<void> verifyOtp(String phone,String code)async{final r=await http.post(Uri.parse('$baseUrl/api/auth/otp/verify'),headers:{'Content-Type':'application/json'},body:jsonEncode({'phone':phone,'code':code}));if(r.statusCode!=200)throw Exception('Неверный OTP');token=jsonDecode(r.body)['accessToken'];await storage.write(key:'access_token',value:token);}Future<List<dynamic>> products()async{final r=await http.get(Uri.parse('$baseUrl/api/products'));if(r.statusCode!=200)throw Exception('Ошибка загрузки товаров');return jsonDecode(r.body);}Future<List<dynamic>> myOrders()async{final r=await _get('/api/me/orders');if(r.statusCode!=200)throw Exception('Ошибка загрузки заказов');return jsonDecode(r.body);}Future<Map<String,dynamic>> createOrder(Map<String,dynamic> order)async{final r=await _post('/api/orders',order);if(r.statusCode!=201)throw Exception('Ошибка оформления заказа');return jsonDecode(r.body);}Future<Map<String,dynamic>> wallet()async{final r=await _get('/api/wallet');if(r.statusCode!=200)throw Exception('Ошибка DADO Wallet');return jsonDecode(r.body);}Future<Map<String,dynamic>> createPaymentIntent(String orderId,String method)async{final r=await _post('/api/payments/intents',{'orderId':orderId,'method':method});if(r.statusCode!=200)throw Exception('Ошибка создания платежа');return jsonDecode(r.body);}Future<void> payWallet(String orderId)async{final r=await _post('/api/wallet/pay',{'orderId':orderId});if(r.statusCode!=200)throw Exception(r.statusCode==400?'Недостаточно средств в DADO Wallet':'Ошибка оплаты');}Future<http.Response> _get(String path)async{token??=await storage.read(key:'access_token');return http.get(Uri.parse('$baseUrl$path'),headers:{if(token!=null)'Authorization':'Bearer $token'});}Future<http.Response> _post(String path,Object body)async{token??=await storage.read(key:'access_token');return http.post(Uri.parse('$baseUrl$path'),headers:{'Content-Type':'application/json',if(token!=null)'Authorization':'Bearer $token'},body:jsonEncode(body));}}
